
-- Catálogo demo anterior y carga previa de este script
delete from public.product_images where product_id in (select id from public.products where sku like 'DEMO-%' or sku like 'BM-%');
delete from public.products where sku like 'DEMO-%' or sku like 'BM-%';
delete from public.categories where parent_id is not null and slug in ('tecnologia','celulares','computadores','tablets','audio','accesorios-tecnologia','hogar-cocina','electrodomesticos','menaje-cocina','muebles','decoracion','moda','calzado','relojes','gafas','bolsos','ropa','deportes','balones','implementos','belleza','fragancias','maquillaje','cuidado-personal','despensa','granos-aceites','bebidas','cafe-endulzantes','smartwatches','televisores','neveras','lavadoras','estufas-hornos','climatizacion','cocina-hogar','pequenos-electrodomesticos','menaje');
delete from public.categories where slug in ('tecnologia','celulares','computadores','tablets','audio','accesorios-tecnologia','hogar-cocina','electrodomesticos','menaje-cocina','muebles','decoracion','moda','calzado','relojes','gafas','bolsos','ropa','deportes','balones','implementos','belleza','fragancias','maquillaje','cuidado-personal','despensa','granos-aceites','bebidas','cafe-endulzantes','smartwatches','televisores','neveras','lavadoras','estufas-hornos','climatizacion','cocina-hogar','pequenos-electrodomesticos','menaje');
delete from public.brands where slug in ('voltix','sonomax','tecnopro','kasa-viva','nordika','urbano-co','tiempo-real','andes-sport','lumen','sabana','apple','samsung','lg','xiaomi','lenovo','hp','jbl','challenger','kalley','electrolux','haceb','mabe','whirlpool','oster','samurai','imusa','home-elements');
delete from public.homepage_banners where desktop_image_url like 'assets/images/demo/%' or desktop_image_url like 'assets/images/catalog/%';
-- Textos sin marcas de demostración
update public.payment_methods set name = replace(name, ' (demo)', '') where name like '% (demo)';
update public.delivery_methods set name = replace(name, ' (demo)', '') where name like '% (demo)';
update public.site_settings set
  data_policy_text = replace(data_policy_text, '[DEMO] ', ''), marketing_consent_text = replace(marketing_consent_text, '[DEMO] ', ''),
  quote_terms = replace(quote_terms, '[DEMO] ', ''), sale_terms = replace(sale_terms, '[DEMO] ', ''), warranty_text = replace(warranty_text, '[DEMO] ', ''),
  announcement_messages = '[{"id":"msg-1","text":"Envíos a todo el país · Precios especiales por mayor","enabled":true,"position":1},{"id":"msg-2","text":"Tecnología y electrodomésticos de las mejores marcas","enabled":true,"position":2},{"id":"msg-3","text":"Paga contra entrega en Barranquilla","enabled":true,"position":3}]'::jsonb,
  updated_at = now() where id = 1;

